-- ---------------------------------------------------------
-- 2. Format row (inactive; is_active is never touched on re-run)
-- ---------------------------------------------------------

insert into public.duelist_circle_formats (
  code, name, version,
  release_cutoff,
  allow_illusion, allow_synchro, allow_xyz, allow_link, allow_pendulum, allow_fusion,
  current_release_stage,
  is_active,
  curated_pool_only,
  boss_route_exempt,
  notes
)
values (
  'duelist_circle_classic_v2',
  'Duelist Circle Classic (Season 2)',
  2,
  '2014-12-31',
  false, false, true, false, false, true,
  1,
  false,
  true,
  true,
  'Season 2 / Duelist Circle 2.0 pool. Eligibility = exactly the 6136 playable cards of data/cardpool/classic-v2-pool.json (include overrides, curated_pool_only). Banlist = duelist_circle_card_limits (Oct 2014 TCG list + group proposal). Proposed rarities in duelist_circle_proposed_rarities. Master Duel: only not_available blocks (Unlimited rooms). boss_route_exempt: Boss evolution monsters + route-exclusive grants are deck-legal and exempt from deck limits, but never offered by draft/shop (owner decision pending). Generated by scripts/cardpool/build-v2-format-migration.mjs.'
)
on conflict (code) do update
set
  name = excluded.name,
  version = excluded.version,
  release_cutoff = excluded.release_cutoff,
  allow_illusion = excluded.allow_illusion,
  allow_synchro = excluded.allow_synchro,
  allow_xyz = excluded.allow_xyz,
  allow_link = excluded.allow_link,
  allow_pendulum = excluded.allow_pendulum,
  allow_fusion = excluded.allow_fusion,
  curated_pool_only = excluded.curated_pool_only,
  boss_route_exempt = excluded.boss_route_exempt,
  notes = excluded.notes,
  updated_at = now();

