-- ---------------------------------------------------------
-- 6. Assertions (any mismatch aborts the whole migration)
-- ---------------------------------------------------------

do $$
declare
  v_format public.duelist_circle_formats;
  v_includes integer;
  v_limits integer;
  v_rarities integer;
begin
  select * into v_format from public.duelist_circle_formats where code = 'duelist_circle_classic_v2';

  select count(*) into v_includes
  from public.format_card_overrides
  where format_id = v_format.id and override_type = 'include';

  select count(*) into v_limits
  from public.duelist_circle_card_limits
  where format_code = 'duelist_circle_classic_v2';

  select count(*) into v_rarities
  from public.duelist_circle_proposed_rarities
  where format_code = 'duelist_circle_classic_v2';

  if v_includes <> 6136 then
    raise exception 'Classic v2 seed: % of 6136 pool cards found in card_catalog (external_card_id mismatch?)', v_includes;
  end if;

  if v_limits <> 185 then
    raise exception 'Classic v2 seed: % of 185 banlist rows matched card_catalog', v_limits;
  end if;

  if v_rarities <> 6136 then
    raise exception 'Classic v2 seed: % of 6136 proposed rarities matched card_catalog', v_rarities;
  end if;

  raise notice 'Classic v2 seed OK: % includes, % banlist rows, % proposed rarities, boss_route_exempt=%, active=%',
    v_includes, v_limits, v_rarities, v_format.boss_route_exempt, v_format.is_active;
end;
$$;

commit;
